<?php
$active_page='coupons'; $page_title='Codes promo';
if(isset($_POST['add_coupon'])){require_once __DIR__ . '/config.php'; $code=strtoupper(trim($_POST['code'])); $pdo->prepare("INSERT INTO coupons (code,reduction,date_expiration) VALUES(?,?,?)")->execute([$code,(int)$_POST['reduction'],$_POST['date_expiration']]); logAction($pdo, 'Ajout coupon', $code); header("Location: coupons.php?success=coupon_added"); exit();}
if(isset($_GET['delete'])){require_once __DIR__ . '/config.php'; $pdo->prepare("DELETE FROM coupons WHERE id=?")->execute([(int)$_GET['delete']]); logAction($pdo, 'Suppression coupon', "ID {$_GET['delete']}"); header("Location: coupons.php?deleted=1"); exit();}
require_once 'header.php';
$coupons=$pdo->query("SELECT * FROM coupons ORDER BY id DESC")->fetchAll();
?>
<div style="display:grid;grid-template-columns:340px 1fr;gap:20px;align-items:start"><div class="panel"><div class="panel-head"><div class="panel-title"><i class="fas fa-plus"></i> Nouveau coupon</div></div><div class="panel-body"><form method="POST"><div class="fg"><label>Code promo</label><input type="text" name="code" placeholder="EX: LUXE20" required style="text-transform:uppercase"></div><div class="fg"><label>Réduction (%)</label><input type="number" name="reduction" min="1" max="100" required></div><div class="fg"><label>Date expiration</label><input type="date" name="date_expiration" required></div><button type="submit" name="add_coupon" class="btn btn-em" style="width:100%">Créer</button></form></div></div><div class="panel"><div class="panel-head"><div class="panel-title"><i class="fas fa-ticket-alt"></i> Coupons actifs (<?= count($coupons) ?>)</div></div><div class="tbl-wrap"><table class="dtable"><thead><tr><th>Code</th><th>Remise</th><th>Expiration</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($coupons as $c): $exp=strtotime($c['date_expiration'])<time(); ?><tr><td style="color:var(--em)"><i class="fas fa-tag"></i> <?= htmlspecialchars($c['code']) ?></td><td style="color:var(--warning)">-<?= $c['reduction'] ?>%</td><td><?= date('d/m/Y',strtotime($c['date_expiration'])) ?></td><td><?= $exp?'<span class="badge badge-red">Expiré</span>':'<span class="badge badge-em">Actif</span>' ?></td><td><a href="?delete=<?= $c['id'] ?>" class="btn btn-danger btn-xs" onclick="return confirm('Supprimer ?')"><i class="fas fa-trash"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once 'footer.php'; ?>